# --- Accessors (added for Company Question Bank) ---

_VARIANT_SUFFIXES = ("-v2", "-v3", "-v4")

# Canonical id aliases so slugs like "goldman-sachs" or "Goldman Sachs" resolve.
COMPANY_ALIASES = {
    "goldman": "goldman_sachs",
    "goldman-sachs": "goldman_sachs",
    "goldman sachs": "goldman_sachs",
    "goldman_sachs": "goldman_sachs",
}

CATEGORY_LABELS = {
    "behavioral": "Behavioral",
    "technical": "Technical",
    "coding": "Coding",
    "system_design": "System Design",
    "hr": "HR",
    "sql": "SQL",
    "oop": "OOP",
    "puzzle": "Puzzle",
    "aptitude": "Aptitude",
    "general": "General",
}


def resolve_company(name) -> Optional[str]:
    """Return the canonical bank company id for a user-facing company name, or None."""
    if not name:
        return None
    key = str(name).strip().lower()
    if key in COMPANY_QUESTIONS:
        return key
    alias = COMPANY_ALIASES.get(key)
    if alias:
        return alias
    flat = key.replace("-", " ").replace("_", " ")
    for cid in COMPANY_QUESTIONS:
        if cid.replace("_", " ") == flat:
            return cid
    return None


def _is_variant(q: dict) -> bool:
    return str(q.get("id", "")).endswith(_VARIANT_SUFFIXES)


def get_questions_by_company(company_id: str, category: Optional[str] = None) -> List[dict]:
    """Non-variant questions for a company, optionally filtered by category."""
    entry = COMPANY_QUESTIONS.get(company_id)
    if not entry:
        return []
    out = []
    for cat, items in entry.get("questions", {}).items():
        if category and cat != category:
            continue
        for q in items:
            if _is_variant(q):
                continue
            out.append(dict(q))
    return out


def get_companies() -> List[dict]:
    """Metadata + per-category counts for every company in the bank (non-variant)."""
    result = []
    for cid, entry in COMPANY_QUESTIONS.items():
        cats = []
        total = 0
        for cat, items in entry.get("questions", {}).items():
            originals = [q for q in items if not _is_variant(q)]
            if not originals:
                continue
            difficulty: dict = {}
            for q in originals:
                d = q.get("difficulty", "medium")
                difficulty[d] = difficulty.get(d, 0) + 1
            cats.append({
                "category": cat,
                "label": CATEGORY_LABELS.get(cat, cat.replace("_", " ").title()),
                "count": len(originals),
                "difficulty": difficulty,
            })
            total += len(originals)
        cats.sort(key=lambda c: c["count"], reverse=True)
        result.append({
            "company_id": cid,
            "name": entry.get("name", cid.title()),
            "icon": entry.get("icon", ""),
            "color": entry.get("color", ""),
            "leadership_principles": entry.get("leadership_principles", []),
            "total_questions": total,
            "categories": cats,
        })
    result.sort(key=lambda c: c["name"].lower())
    return result
